// ---------------------------------------------------------------------------
// Paper Split — generated by Dialcraft
// target: Amazfit Bip 6 (bip-6, 390×450, s)
//
// Built against the Zepp OS watchface API:
//   widgets  https://docs.zepp.com/docs/watchface/api/hmUI/widget/
//   layout   px() scales from app.json designWidth = 390
//   states   show_level = normal / AOD / edit
// Design-spec reminders: preview time 10:09:36, 2px safe edge, AOD keeps
// the pixel budget under 10% with a black background and no second hand.
// ---------------------------------------------------------------------------
import ui from '@zos/ui'
import * as zosFs from '@zos/fs'

const A = (p) => `images/${p}`

// ---- image arrays (frame order matters: digits 0-9, week 1-7) ----
const img_Minute_Main_u13e = [
  A('reference/minute-0.png'),
  A('reference/minute-1.png'),
  A('reference/minute-2.png'),
  A('reference/minute-3.png'),
  A('reference/minute-4.png'),
  A('reference/minute-5.png'),
  A('reference/minute-6.png'),
  A('reference/minute-7.png'),
  A('reference/minute-8.png'),
  A('reference/minute-9.png'),
]

const img_Hour_Main_u4i0 = [
  A('reference/hour-0.png'),
  A('reference/hour-1.png'),
  A('reference/hour-2.png'),
  A('reference/hour-3.png'),
  A('reference/hour-4.png'),
  A('reference/hour-5.png'),
  A('reference/hour-6.png'),
  A('reference/hour-7.png'),
  A('reference/hour-8.png'),
  A('reference/hour-9.png'),
]

const img_Minute_22vd = [
  A('font_2_0.png'),
  A('font_2_1.png'),
  A('font_2_2.png'),
  A('font_2_3.png'),
  A('font_2_4.png'),
  A('font_2_5.png'),
  A('font_2_6.png'),
  A('font_2_7.png'),
  A('font_2_8.png'),
  A('font_2_9.png'),
]

const img_Hour_22av = [
  A('font_3_0.png'),
  A('font_3_1.png'),
  A('font_3_2.png'),
  A('font_3_3.png'),
  A('font_3_4.png'),
  A('font_3_5.png'),
  A('font_3_6.png'),
  A('font_3_7.png'),
  A('font_3_8.png'),
  A('font_3_9.png'),
]

// ---- saved choices (theme / variant): survive a restart and reach the always-on screen ----
const dcGet = (k) => {
  try { const v = Number(zosFs.readFileSync({ path: 'dc_' + k + '.txt', options: { encoding: 'utf8' } })); if (v) return v } catch (e) {}
  try { if (typeof hmFS !== 'undefined') return Number(hmFS.SysProGetInt(k)) || 0 } catch (e) {}
  return 0
}
const dcSet = (k, v) => {
  try { zosFs.writeFileSync({ path: 'dc_' + k + '.txt', data: String(v), options: { encoding: 'utf8' } }) } catch (e) {}
  try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt(k, v) } catch (e) {}
}

WatchFace({
  initView() {
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    variantIdx = dcGet('dialcraft_variant')

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Scene (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: A('approved-artwork.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Minute Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(39),
      minute_startY: px(216),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Main_u13e,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(32),
      hour_startY: px(41),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_Main_u4i0,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(210),
      minute_startY: px(188),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_22vd,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Colon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(180),
      y: px(196),
      src: A('symbol_u003a.png'),
      show_level: ui.show_level.ONLY_AOD
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(77),
      hour_startY: px(188),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_22av,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Hour flap (IMG)
    const variants_0 = [A('sp/paper_005.png'), A('sp/paper_001.png'), A('sp/paper_002.png'), A('sp/paper_003.png'), A('sp/paper_004.png'), A('sp/paper_000.png')]
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(48),
      y: px(88),
      src: variants_0[variantIdx % variants_0.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.upperFold = variant_0
    F.upperFold = variants_0

    // Minute flap (IMG)
    const variants_1 = [A('sp/paper_005.png'), A('sp/paper_001.png'), A('sp/paper_002.png'), A('sp/paper_003.png'), A('sp/paper_004.png'), A('sp/paper_000.png')]
    const variant_1 = ui.createWidget(ui.widget.IMG, {
      x: px(48),
      y: px(312),
      src: variants_1[variantIdx % variants_1.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.lowerFold = variant_1
    F.lowerFold = variants_1

    // a Tap zone set to "Cycle variants" calls this
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length, variants_1.length)
      dcSet('dialcraft_variant', variantIdx)
      variant_0.setProperty(ui.prop.SRC, variants_0[variantIdx % variants_0.length])
      variant_1.setProperty(ui.prop.SRC, variants_1[variantIdx % variants_1.length])
    }

    // ---- user code (project.userCode) ----
    {const V = {"upperFold":{"0":5,"1":1,"2":2,"3":3,"4":4,"__blank":0},"lowerFold":{"0":5,"1":1,"2":2,"3":3,"4":4,"__blank":0}}; const P=[], D=[], MS=100; const tick=()=>{
    const d=new Date(), phase=Math.floor(d.getMilliseconds()/100);
    for(const [h,y,active] of [['upperFold',88,d.getMinutes()===0],['lowerFold',312,true]]){
     if(active&&d.getSeconds()===0&&phase<5)slot(h)(48,y,V[h][phase]);else slot(h).hide();
    }
    };   // ---- shared runtime: slot setter that skips unchanged calls, and a loop that runs only while the face is on screen ----
      const SL = {};
      const slot = (h) => {
        if (SL[h]) return SL[h];
        const w = W[h], f = F[h]; let key = '';
        const s = (x, y, i, ww, hh) => {
          const k = x + '|' + y + '|' + i + '|' + ww + '|' + hh;
          if (k === key) return;
          key = k;
          const p = { x: pxv(x), y: pxv(y) };
          if (i !== undefined) p.src = f[i];
          if (ww !== undefined) { p.w = pxv(ww); p.h = pxv(hh); }
          w.setProperty(ui.prop.MORE, p);
        };
        s.hide = () => { if (key === 'hide') return; key = 'hide'; w.setProperty(ui.prop.MORE, { src: f[V[h].__blank] }); };
        return (SL[h] = s);
      };
      let gen = 0, running = false;
      const safe = () => { tick(); };
      const loop = (g) => {
        if (!running || g !== gen) return;
        safe();
        if (running && g === gen) { try { setTimeout(() => loop(g), MS); } catch (e) {} }
      };
      const start = () => {
        gen++; running = true; const g = gen;
        try { setTimeout(() => loop(g), MS); } catch (e) {}
        safe();
      };
      const stop = () => { running = false; gen++; };
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop });
      start();
    }

    // ---- screen corners (the face switcher draws the live face square) ----
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(0), w: px(86), h: px(86), src: A('corner_tl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(0), w: px(86), h: px(86), src: A('corner_tr.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(364), w: px(86), h: px(86), src: A('corner_bl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(364), w: px(86), h: px(86), src: A('corner_br.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
  },

  build() {
    this.initView()
  },
})
